#!/usr/bin/env bash
# Installs the observability stack @@STACK_NAME@@ as systemd services (no containers).
# Generated by render.sh. Run as root on the monitoring host, from this folder:
#   sudo ./install.sh              install / update configs and units, (re)start the services
#   sudo ./install.sh --download   also download the binaries (linux-amd64) from GitHub / grafana.com
# Without --download, put the binaries in place first (air-gapped hosts):
#   /usr/local/bin/otelcol-contrib  @@OTELCOL_VERSION@@
#   /usr/local/bin/prometheus       @@PROMETHEUS_VERSION@@
#   /usr/local/bin/tempo            @@TEMPO_VERSION@@
#   /opt/@@STACK_NAME@@/grafana     Grafana @@GRAFANA_VERSION@@ (unpacked tarball)   [GRAFANA_MODE=bundled]
#   /usr/local/bin/node_exporter    @@NODE_EXPORTER_VERSION@@                        [INFRA_METRICS=node]
set -euo pipefail
cd "$(dirname "$0")"
[ "$(id -u)" -eq 0 ] || { echo "run as root (sudo)" >&2; exit 1; }

STACK=@@STACK_NAME@@
CONFIG_DIR=@@CONFIG_DIR@@
DATA_DIR=@@DATA_DIR@@
SERVICES="@@HOST_SERVICES@@"

download() {   # url, member to extract (glob), destination
  local tmp; tmp=$(mktemp -d)
  echo "downloading $1"
  curl -fsSL "$1" -o "$tmp/pkg.tar.gz"
  tar -xzf "$tmp/pkg.tar.gz" -C "$tmp"
  # shellcheck disable=SC2086
  install -m 0755 $(find "$tmp" -type f -name "$2" | head -1) "$3"
  rm -rf "$tmp"
}

if [ "${1:-}" = "--download" ]; then
  download "https://github.com/open-telemetry/opentelemetry-collector-releases/releases/download/v@@OTELCOL_VERSION@@/otelcol-contrib_@@OTELCOL_VERSION@@_linux_amd64.tar.gz" otelcol-contrib /usr/local/bin/otelcol-contrib
  download "https://github.com/prometheus/prometheus/releases/download/v@@PROMETHEUS_VERSION@@/prometheus-@@PROMETHEUS_VERSION@@.linux-amd64.tar.gz" prometheus /usr/local/bin/prometheus
  download "https://github.com/grafana/tempo/releases/download/v@@TEMPO_VERSION@@/tempo_@@TEMPO_VERSION@@_linux_amd64.tar.gz" tempo /usr/local/bin/tempo
  case " $SERVICES " in *" node-exporter "*)
    download "https://github.com/prometheus/node_exporter/releases/download/v@@NODE_EXPORTER_VERSION@@/node_exporter-@@NODE_EXPORTER_VERSION@@.linux-amd64.tar.gz" node_exporter /usr/local/bin/node_exporter ;;
  esac
  case " $SERVICES " in *" grafana "*)
    tmp=$(mktemp -d)
    echo "downloading Grafana @@GRAFANA_VERSION@@"
    curl -fsSL "https://dl.grafana.com/oss/release/grafana-@@GRAFANA_VERSION@@.linux-amd64.tar.gz" -o "$tmp/grafana.tar.gz"
    rm -rf "/opt/$STACK/grafana"; mkdir -p "/opt/$STACK/grafana"
    tar -xzf "$tmp/grafana.tar.gz" -C "/opt/$STACK/grafana" --strip-components=1
    rm -rf "$tmp" ;;
  esac
fi

for bin in /usr/local/bin/otelcol-contrib /usr/local/bin/prometheus /usr/local/bin/tempo; do
  [ -x "$bin" ] || { echo "$bin missing (use --download, or install it)" >&2; exit 1; }
done
case " $SERVICES " in *" grafana "*) [ -x "/opt/$STACK/grafana/bin/grafana" ] || { echo "/opt/$STACK/grafana missing" >&2; exit 1; } ;; esac
case " $SERVICES " in *" node-exporter "*) [ -x /usr/local/bin/node_exporter ] || { echo "/usr/local/bin/node_exporter missing" >&2; exit 1; } ;; esac

id "$STACK" >/dev/null 2>&1 || useradd --system --no-create-home --shell /usr/sbin/nologin "$STACK"

# configs (replaced on every run), data (kept)
mkdir -p "$CONFIG_DIR"
rm -rf "$CONFIG_DIR/otel-collector" "$CONFIG_DIR/prometheus" "$CONFIG_DIR/tempo" "$CONFIG_DIR/grafana/provisioning" "$CONFIG_DIR/grafana/dashboards"
cp -r config/. "$CONFIG_DIR/"
[ -d grafana ] && { mkdir -p "$CONFIG_DIR/grafana"; cp -r grafana/. "$CONFIG_DIR/grafana/"; }
if [ -f grafana-admin.env ] && [ ! -f "$CONFIG_DIR/grafana/admin.env" ]; then
  install -m 0600 -o root -g root grafana-admin.env "$CONFIG_DIR/grafana/admin.env"
fi
chown -R root:"$STACK" "$CONFIG_DIR"; chmod -R g+rX,o-rwx "$CONFIG_DIR"
mkdir -p "$DATA_DIR/prometheus" "$DATA_DIR/tempo"
case " $SERVICES " in *" grafana "*) mkdir -p "$DATA_DIR/grafana/log" "$DATA_DIR/grafana/plugins" ;; esac
chown -R "$STACK:$STACK" "$DATA_DIR"; chmod 0750 "$DATA_DIR"

for s in $SERVICES; do
  install -m 0644 "systemd/$s.service" "/etc/systemd/system/$STACK-$s.service"
done
systemctl daemon-reload
for s in $SERVICES; do
  systemctl enable "$STACK-$s.service" >/dev/null
  systemctl restart "$STACK-$s.service"
done
sleep 5
systemctl --no-pager --lines=0 status $(for s in $SERVICES; do printf '%s-%s ' "$STACK" "$s"; done) || true
echo
echo "Installed. OTLP: @@BIND_ADDRESS@@:4317 (gRPC) / :4318 (HTTP); open them on the firewall for the app hosts only."
